from PIL import Image, ImageDraw
im = Image.open('radiograph.jpg').convert('RGB')
def tile(x1,y1,x2,y2,name,scale=4):
    c = im.crop((x1,y1,x2,y2)).resize(((x2-x1)*scale,(y2-y1)*scale), Image.LANCZOS)
    d = ImageDraw.Draw(c)
    for x in range(x1 - x1%50, x2, 50):
        px=(x-x1)*scale; d.line([(px,0),(px,c.height)],fill=(255,60,60),width=1); d.text((px+2,2),str(x),fill=(255,255,0))
    for y in range(y1 - y1%50, y2, 50):
        py=(y-y1)*scale; d.line([(0,py),(c.width,py)],fill=(0,255,0),width=1); d.text((2,py+2),str(y),fill=(0,255,255))
    c.save(name); print(name,c.size)
